INSERT INTO `home_benefits` (`id`, `title`, `content`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Top Tier Guidance', 'Our highly qualified and experienced faculty, including doctors and subject matter experts, provide top-tier guidance and mentorship to ensure in-depth conceptual clarity.', 0, 1, '2026-01-02 04:28:41', '2026-01-02 04:28:41'),
(2, 'Study Material', 'We provide well-researched, NCERT-aligned study material that covers both Class 11 and 12 syllabus along with advanced-level NEET topics for effective learning.', 0, 1, '2026-01-02 04:29:01', '2026-01-02 04:29:01');
INSERT INTO `home_services` (`id`, `title`, `description`, `footer_text`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, '1-Year Medical Course', 'A focused one-year fast-track program designed to master the NEET syllabus while helping students excel in their Class 12 board exams.', 'Make Sure Your Child Is In The Race.', 0, 1, '2026-01-02 04:23:03', '2026-01-02 04:23:03'),
(2, '2-Year Medical Course', 'A comprehensive two-year program building a rock-solid foundation for Class 11 and 12, offering the most trusted NEET coaching in Patiala to ensure long-term medical success.', 'Limited seats lifetime opportunity', 0, 1, '2026-01-02 04:23:21', '2026-01-02 04:23:21'),
(3, 'Droppers Batch (1-Year Ascend)', 'A dedicated one-year intensive course providing specialized NEET coaching in Patiala for repeaters looking to bridge academic gaps and secure a top-tier medical rank.', 'A defining step toward your medical career', 0, 1, '2026-01-02 04:24:06', '2026-01-02 04:24:06');
